ROOT=Path(__file__).resolve().parent
FX=ROOT.parents[2];H=FX/'menu-repair-01/runtime/helpers';OUT=ROOT/'build'
VENV=FX.parent/'sony-firmware-20261024/stage4-windows-collab/mac-verification/.venv/bin/python'
commands=[]
def sha(path):return hashlib.sha256(path.read_bytes()).hexdigest()
def write(name,obj):(OUT/name).write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n')
def run(args,name,env=None):
 start=time.monotonic();p=subprocess.run([str(a) for a in args],cwd=ROOT,env=env,text=True,capture_output=True)
 receipt={'command':[str(a) for a in args],'exit':p.returncode,'seconds':time.monotonic()-start,'stdout':p.stdout,'stderr':p.stderr}
 commands.append({'name':name,**receipt});write('commands.json',commands)
 (OUT/(name+'.log')).write_text(p.stdout+p.stderr)
 if p.returncode:raise RuntimeError(f'{name} failed ({p.returncode}): {p.stderr[-2500:]} {p.stdout[-1500:]}')
 return receipt

def tables():
 r=lambda n:(n+127)//255;q=lambda n:(n+8)//17
 s=['/* Generated by build_and_test.py; v8 exact integer formula. */']
 def add(name,rows):
  s.append('static const uint8_t '+name+' = {')
  s.extend('{'+','.join(map(str,row))+'},' for row in rows);s.append('};')
 add('channel4[256][256]',[[q(r(17*(cs*a+cd*(255-a)))) for cs in range(16) for cd in range(16)] for a in range(256)])
 add('alpha4[256][16]',[[q(a+r(ad*17*(255-a))) for ad in range(16)] for a in range(256)])
 s.append('static const uint8_t quant4[256]={'+','.join(str(q(v)) for v in range(256))+'};')
 (ROOT/'tables-v9.inc').write_text('\n'.join(s)+'\n')


